 return `<div class="ms-book"><div class="ms-abc" role="group" aria-label="ABC order">${esc(T.alphabet)}</div><div class="ms-page-tabs" role="group" aria-label="Dictionary pages">${book.pages.map((pg,i)=>button('book-page',guideWords(pg)||`Page ${i+1}`,`data-ms-book="${context}" data-ms-page="${esc(pg.id)}" aria-pressed="${pg.id===pageId}"`)).join('')}</div><section class="ms-book-paper" aria-label="${esc(guide?`Guide words: ${guide}`:'Dictionary page')}">${page?`<header class="ms-guide"><span>Guide words</span><strong>${esc(guide||'Page unavailable')}</strong></header><div class="ms-page-text">${page.entries.length?`<dl>${page.entries.map(e=>`<div class="ms-book-entry${highlight&&e.id===targetId?' ms-found':''}" id="ms-${context}-entry-${esc(e.id)}" tabindex="-1"><dt>${esc(e.word)}${highlight&&e.id===targetId?'<span class="ms-found-label">Found on this page</span>':''}</dt><dd>${esc(e.definition)}</dd></div>`).join('')}</dl>`:p(T.emptyPage)}</div>`:p(pageId===null&&book.pages.length?'Choose a dictionary page.':T.pageUnavailable)}</section>${page?p(`Page ${book.pages.indexOf(page)+1} of ${book.pages.length}`):''}</div>`;
