 const s=r.source,last=r.checks.at(-1),book=v.book,withBook=['E1','E3','E4'].includes(s.id)&&book;
 const page=own(l.practicePages,s.id)?l.practicePages[s.id]:own(v.root,'dictionary')&&book?.pages.some(p=>p.id===v.dictionaryDraft?.pageId)?v.dictionaryDraft.pageId:null;
 return `<section class="ms-job"><h2 id="ms-task" tabindex="-1">${esc(s.title)}</h2>${p(['B5','E2'].includes(s.id)?'A true thing about language':'A story from Willowbank')}${s.tag?`<p class="ms-tag">Word part: <strong>${esc(s.tag)}</strong></p>`:''}${p(s.prompt)}${s.steps.length?`<ol class="ms-guided">${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}${s.kind==='order'?`<div class="ms-abc" role="group" aria-label="ABC order">${esc(T.alphabet)}</div>`:''}<div class="ms-job-layout${withBook?' ms-with-book':''}">${withBook?bookPaper(book,page,'practice'):''}<div>${jobControls(r,l)}<div class="ms-actions">${button('check-job','Check this job')}${button('keep-version','Keep this version')}${button('next-job','Next job')}</div>${last?`<aside class="ms-feedback" id="ms-job-feedback" tabindex="-1">${!c.sameMarketWork(last.work,r.work)?p('Checked before your last change'):''}${last.feedback.map(p).join('')}${p('Practice with these words')}</aside>`:''}</div></div>${panel(l,'help','Help',`${button('hint','A hint')}${button('example','Read an example')}${button('skip','Skip for now')}${r.help.hint?`<aside id="ms-hint" tabindex="-1">${p(s.hint)}</aside>`:''}${r.help.example?`<aside id="ms-example" tabindex="-1">${p(s.example)}</aside>`:''}`)}${panel(l,'versions','Kept versions',`${own(r,'firstKept')?snapshot(s,r.firstKept,'First kept version'):p('Keep a version, even if it is unfinished.')}${own(r,'latestKept')?snapshot(s,r.latestKept,'Latest kept version'):''}`)}${panel(l,'jobs','Choose a job',jobShelf(v))}</section>`;
